-- PPE Hub locale merge from docs/LanguageAddon/Translations/PpeHub.csv
-- Data-only UPDATE of ppe_categories and ppe_sections. No ALTER TABLE. No published-flag changes.
-- Run in the Supabase SQL editor when ready. Take a backup first.
-- Merges en/it/fr/de/es into existing JSONB locale objects.
-- Skipped: blank cells, "" placeholders, empty arrays, empty objects, and lone "." cells.
-- Warning: the admin PPE Hub editor still saves only en/it. Saving a category there will wipe fr/de/es until that editor is extended.

BEGIN;

-- ppe_categories hand-and-arm-protection
UPDATE ppe_categories
SET title_locales = COALESCE(title_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Hand and arm protection"'::jsonb,
    'it', '"Protezione di mani e braccia"'::jsonb,
    'fr', '"Protection des mains et des bras"'::jsonb,
    'de', '"Hand- und Armschutz"'::jsonb,
    'es', '"Protección de las manos y los brazos"'::jsonb
  ),
  summary_locales = COALESCE(summary_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Glove standards for mechanical, cut and thermal risks; selection and markings."'::jsonb,
    'it', '"Norme per guanti contro rischi meccanici, da taglio e termici; scelta e marcature."'::jsonb,
    'fr', '"Normes relatives aux gants contre les risques mécaniques, de coupure et thermiques ; choix et marquages."'::jsonb,
    'de', '"Normen für Handschuhe gegen mechanische, Schnitt- und thermische Risiken; Auswahl und Kennzeichnungen."'::jsonb,
    'es', '"Normas para guantes contra riesgos mecánicos, de corte y térmicos; selección y marcados."'::jsonb
  )
WHERE id = '7c329c88-eb36-4886-a1ec-1b1b2f50c00a';

